from scipy.optimize import least_squares
import warnings; warnings.filterwarnings('ignore')
e=df['eps'].values;t=df['T'].values;s=df['sigma'].values
def run(fn,npar,trials=10):
    best=None
    np.random.seed(2)
    for _ in range(trials):
        p0=np.random.randn(npar)*0.7
        try:
            r=least_squares(lambda p: np.nan_to_num(fn(p)-s,nan=1e3,posinf=1e3,neginf=-1e3), p0, max_nfev=800)
            if best is None or r.cost<best.cost: best=r
        except Exception as ex: pass
    return best
base=lambda p: p[0]+p[1]*(e*np.exp(-p[2]*e))/t
F={
 'eps^a': lambda q: np.abs(e)**q[0],
 'eps^a*exp(-k eps)': lambda q: np.abs(e)**q[0]*np.exp(-q[1]*e),
 '1-exp(-k eps)': lambda q: 1-np.exp(-q[0]*e),
 'exp(-k eps)': lambda q: np.exp(-q[0]*e),
 'eps/(k+eps)': lambda q: e/(np.abs(q[0])+e),
}
G={
 'exp(-k/T)': lambda q: np.exp(-q[0]/t),
 'T^b': lambda q: np.abs(t)**q[0],
 'exp(-k T)': lambda q: np.exp(-q[0]*t),
 'exp(-k/T^2)': lambda q: np.exp(-q[0]/t**2),
}
out=[]
for fn_name,fF in F.items():
    nF=2 if fn_name=='eps^a*exp(-k eps)' else 1
    for gn,gG in G.items():
        def model(p,fF=fF,gG=gG,nF=nF):
            return base(p)+p[3]*fF(p[4:4+nF])*gG(p[4+nF:5+nF])
        b=run(model,5+nF,trials=8)
        out.append((float(np.var(b.fun)/np.var(s)),fn_name,gn,list(np.round(b.x,4))))
out.sort(key=lambda x:x[0])
for r in out[:8]: print(r)
